<script setup lang="ts">
import { message } from 'ant-design-vue';import { onMounted,reactive,ref } from 'vue';import AdminPageHeader from '@/components/admin/AdminPageHeader.vue';import { platformFlowApi } from '@/services/platformFlowDashboard';import type { PlatformFlowDefinition } from '@/types/platformFlowDashboard'
const items=ref<PlatformFlowDefinition[]>([]),selected=ref<PlatformFlowDefinition|null>(null),versions=ref<any[]>([]),error=ref('');const form=reactive({code:'',name:'',description:'',draft:'{"steps":["VALIDATE_INPUT","CREATE_PLATFORM_TASK","RETURN_RESULT"]}'});async function load(){items.value=await platformFlowApi.adminList()}function select(v:PlatformFlowDefinition){selected.value=v;Object.assign(form,{code:v.code,name:v.name,description:v.description||'',draft:JSON.stringify(v.draft,null,2)});void platformFlowApi.versions(v.id).then(r=>versions.value=r)}async function save(){try{const draft=JSON.parse(form.draft);selected.value=selected.value?await platformFlowApi.save(selected.value.id,{name:form.name,description:form.description,draft,expectedVersion:selected.value.version}):await platformFlowApi.create({code:form.code,name:form.name,description:form.description,draft});message.success('Flow 草稿已保存');await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}}async function check(){if(!selected.value)return;const r=await platformFlowApi.check(selected.value.id);r.valid?message.success('校验通过'):message.error(r.issues.join('; '))}async function publish(){if(!selected.value)return;await platformFlowApi.publish(selected.value.id,selected.value.version);message.success('Flow 已发布');await load()}onMounted(()=>load().catch(e=>error.value=e.message))
</script><template><section class="admin-page"><AdminPageHeader title="平台 Flow 管理" description="平台流程独立发布，不绑定任何 systemId/tenantId。"><template #actions><a-button @click="selected=null">新建</a-button><a-button type="primary" @click="save">保存草稿</a-button></template></AdminPageHeader><a-alert v-if="error" type="error" :message="error"/><div class="editor"><aside><button v-for="item in items" :key="item.id" @click="select(item)"><strong>{{ item.name }}</strong><small>{{ item.status }} · v{{ item.activeVersionNumber||'-' }}</small></button></aside><main><a-form layout="vertical"><a-form-item label="代码"><a-input v-model:value="form.code" :disabled="!!selected"/></a-form-item><a-form-item label="名称"><a-input v-model:value="form.name"/></a-form-item><a-form-item label="说明"><a-input v-model:value="form.description"/></a-form-item><a-form-item label="步骤 JSON"><a-textarea v-model:value="form.draft" :rows="10"/></a-form-item><a-space><a-button :disabled="!selected" @click="check">校验</a-button><a-button :disabled="!selected" type="primary" @click="publish">发布</a-button></a-space></a-form><p v-if="versions.length">已发布版本：{{ versions.map(v=>`v${v.versionNumber}`).join('、') }}</p></main></div></section></template><style scoped>.admin-page{display:grid;gap:16px}.editor{display:grid;grid-template-columns:240px 1fr;gap:16px}.editor aside{display:grid;align-content:start;gap:7px}.editor aside button{display:grid;gap:4px;text-align:left;padding:11px;border:1px solid #dce3e8;border-radius:6px;background:#fff}.editor main{padding:18px;border:1px solid #dce3e8;border-radius:8px;background:#fff}@media(max-width:760px){.editor{grid-template-columns:1fr}}</style>
